8cbecd92a7af91bcb34e1d4f35b2726dee80d197dd0c","hash_paquete_atestado":"b9a0ca43729f14093cd5e6e34212c2a03226fe9556345a24a8796e117d75d6c9","veredicto":"PASS","juez":"Claude independiente 2026-11-24 04:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":173,"familia":"UI_MESSAGES","diferencias":"Contraste funcional: BLOQUEAR mostrar resumen de selección con planes en cuotas sin el texto En el checkout pagarás hoy la primera cuota de cada plan seleccionado., o mostrarlo cuando solo hay pagos únicos.","residual":"","complementa":null},{"codigo":"S10-C12","version":1,"eval_id":829,"hash_version_atestado":"b841c3d5259d396547b16cd11ebe8662b79bc531693c66e2d66bb5563f781e79","hash_paquete_atestado":"de13b1278c54f2020d223c6f08d32e0f2bdeab961719af573b9d74639fa7df40","veredicto":"PASS","juez":"Claude independiente 2026-11-24 04:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":188,"familia":"OBSERVABILITY","diferencias":"Contraste funcional: BLOQUEAR emitir log backend en texto libre sin estructura JSON con timestamp, level, request_id, user_session_id anónimo, pantalla, accion, duracion_ms y error_code cuando aplique; no exponer PII.","residual":"","complementa":null},{"codigo":"S10-C13","version":1,"eval_id":830,"hash_version_atestado":"adbbf78746edd70809c6b99408beeb4e385813f0b6f48445c39f1bc3e84ca03a","hash_paquete_atestado":"73b4c907f0fb869def2c1686b506d52927cd257f54e668c0bde5d444e7946700","veredicto":"PASS","juez":"Claude independiente 2026-11-24 04:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":213,"familia":"API_DATA_CONTRACT","diferencias":"Contraste funcional: BLOQUEAR exponer endpoint sin prefijo de versión o sustituir versión incompatible sin coexistencia durante migración completa.","residual":"","complementa":null},{"codigo":"S10-C14","version":1,"eval_id":831,"hash_version_atestado":"9cf7af30118dfbca46c2998922f2b201430a1b35ca0633b351e8d4353f8e42e3","hash_paquete_atestado":"e6ad47159f5712325705fd79fefee3735b497de9c47c52ea99ebc71614fffea1","veredicto":"PASS","juez":"Claude independiente 2026-11-24 04:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":231,"familia":"B2B_PARTNERS","diferencias":"Contraste funcional: BLOQUEAR que LF invente o sustituya monto de descuento, plazo o condiciones de oferta cargadas por aliado; LF presenta condiciones autorizadas.","residual":"","complementa":null},{"codigo":"S10-C15","version":1,"eval_id":832,"hash_version_atestado":"91994a4085fe81404755d0eb35fa82bcc083b4c13bd22c8b584b48bcf0baee94","hash_paquete_atestado":"a20c6a5ff69c85b0e8a313490baeedd5e4edf61f13692bb04acc6e94e0800392","veredicto":"PASS","juez":"Claude independiente 2026-11-24 04:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":237,"familia":"ASSETS_ICONS","diferencias":"Contraste funcional: BLOQUEAR uso en prototipo de nombres o logos reales de aliados sin autorización documentada; utilizar placeholder genérico o ficticio. No gobierna logos de medios de pago de S6-C14.","residual":"","complementa":null},{"codigo":"S10-C16","version":1,"eval_id":833,"hash_version_atestado":"8a43dad6fdbca0ef37f537ee97164bafe721d4a802e3244f7cd6a7b4f4a8714b","hash_paquete_atestado":"1f99b3ad92798e98326e161358f794fed5740ee95ffb22b78c75309b252b3ada","veredicto":"PASS","juez":"Claude independiente 2026-11-24 04:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":0.9,"observacion":"copy delegado a la legada, no literal"},"COH_EFECTO":{"puntaje":1}},"legada_id":283,"familia":"ACTIONS","diferencias":"Contraste funcional: BLOQUEAR checkout sin acción visible de soporte WhatsApp cuando exista canal LF autorizado; copy de ayuda según legada, sin inventar número ni disponibilidad.","residual":"","complementa":null}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA' AND hash=p->>'hash_version_atestado') THEN RAISE EXCEPTION 'S10_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S10_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s10_juicios_16_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S10_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision'<>'AUTO' THEN RAISE EXCEPTION 'S10_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S10_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S10_COVERAGE_DRIFT %',lid; END IF;
 IF p->>'complementa' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo WHERE c.legacy_id=lid AND c.nucleo_codigo=p->>'complementa' AND c.estado_cobertura='PARCIAL' AND v.estado='PUBLICADA') THEN RAISE EXCEPTION 'S10_COMPLEMENT_DRIFT %',lid; END IF;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 residual:=coalesce(p->>'residual',''); diff:=p->>'diferencias'||CASE WHEN residual<>'' THEN ' Residual: '||residual ELSE '' END;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,CASE WHEN residual='' THEN 'REEMPLAZADA' ELSE 'PARCIAL' END,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S10 2026-11-24 01:50','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S10 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S10_SOURCE_MISSING %',lid; END IF;
 n:=n+1;
 END LOOP;
 IF n<>16 OR pub<>16 OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>16) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S10_READBACK_FAIL n=% pub=% links=%',n,pub,links; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S10_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S10_PASS 16 JUICIOS 16 AUTO links=% DPIG03=0',links;
END $s10$;
COMMIT;
